<?php
require_once 'koneksi.php'; function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=(int)($_GET['id']??0);$stmt=$conn->prepare("SELECT id,nomor_antrian,total,status,created_at,metode_bayar,uang_diterima,kembalian FROM pesanan WHERE id=?");$stmt->bind_param('i',$id);$stmt->execute();$order=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$order){http_response_code(404);die('Nota tidak ditemukan.');}
$stmt=$conn->prepare("SELECT m.nama,pd.qty,pd.subtotal FROM pesanan_detail pd LEFT JOIN menu m ON m.id=pd.menu_id WHERE pd.pesanan_id=?");$stmt->bind_param('i',$id);$stmt->execute();$items=$stmt->get_result();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nota #<?= (int)$order['nomor_antrian'] ?></title><style>body{font:14px Arial;max-width:360px;margin:24px auto;padding:16px;color:#172b3a}.center{text-align:center}.line{border-top:1px dashed #888;margin:12px 0}.row{display:flex;justify-content:space-between;margin:8px 0}button{padding:10px 16px}@media print{button{display:none}body{margin:0}}</style></head><body><div class="center"><h2>KANTIN SEKOLAH</h2><p>Bukti Pembayaran</p><h1>ANTREAN #<?= (int)$order['nomor_antrian'] ?></h1></div><div class="line"></div><p>Tanggal: <?= e(date('d-m-Y H:i',strtotime($order['created_at']))) ?></p><?php while($it=$items->fetch_assoc()): ?><div class="row"><span><?= e($it['nama']) ?> × <?= (int)$it['qty'] ?></span><strong>Rp <?= number_format((int)$it['subtotal'],0,',','.') ?></strong></div><?php endwhile; ?><div class="line"></div><div class="row"><strong>Total</strong><strong>Rp <?= number_format((int)$order['total'],0,',','.') ?></strong></div><div class="row"><span>Metode</span><span><?= strtoupper(e($order['metode_bayar']??'tunai')) ?></span></div><div class="row"><span>Dibayar</span><span>Rp <?= number_format((int)($order['uang_diterima']??0),0,',','.') ?></span></div><div class="row"><span>Kembalian</span><span>Rp <?= number_format((int)($order['kembalian']??0),0,',','.') ?></span></div><div class="line"></div><p class="center">Terima kasih telah berbelanja.</p><div class="center"><button onclick="window.print()">Cetak Struk</button></div></body></html>